fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and switch to the Knowledge Hub app. The default landing is the Classify screen (fa-tags icon). In the left nav within Classify, click the 'Pipeline' section, then click the primary 'Run Pipeline' button in the top-right header. Success is that the Pipeline Monitor renders its KPI strip and 'Recent Processing' feed, AND that clicking Run Pipeline puts the pipeline into a running/monitoring state (a progress bar with a stage label and percent appears, OR the run kicks off with pause/cancel controls) — you do NOT need to wait for the run to finish. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The Classify screen loads with a left-nav rail and the Pipeline section shows a KPI strip and a 'Recent Processing' feed",
    "Clicking 'Run Pipeline' transitions to a running state — a progress bar with a stage label and percentage, OR pause/cancel controls appear (a valid already-running or empty-source state also counts)",
    "No error messages, blank screens, or crash pages"
  ]
}
